def maxUncrossedLines(top, bottom):
    n = len(bottom)
    prev = [0] * (n + 1)
    for x in top:
        cur = [0] * (n + 1)
        for j in range(1, n + 1):
            if x == bottom[j - 1]:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    return prev[n]
